#include <algorithm>
#include <print>
#include <vector>

int main() {
    std::vector<int> a = {3, 1, 3, 2, 1, 5, 2};
    std::sort(a.begin(), a.end());
    auto last = std::unique(a.begin(), a.end());
    for (int v : a) std::print("{} ", v);
    std::println("边界下标 {}，size {}", last - a.begin(), a.size());
    // 尾巴里的 3 3 5 是被搬走的旧值，size 一格没少
    std::vector<int> b = {3, 1, 3, 2, 1, 5, 2};
    auto last2 = std::unique(b.begin(), b.end());
    for (int v : b) std::print("{} ", v);
    std::println("没排序 size {}", b.size());
    // 没有一对相同的挨着，一格都没搬动，边界就落在 end
    return 0;
}

