#include <algorithm>
#include <print>
#include <vector>

int main() {
    std::vector<int> a = {3, 1, 3, 2, 1, 5};
    std::sort(a.begin(), a.end());
    a.erase(std::unique(a.begin(), a.end()), a.end());
    for (int v : a) std::print("{} ", v);
    std::println("{}", a.size());
    return 0;
}
#include <algorithm>
#include <print>
#include <vector>

int main() {
    std::vector<int> v = {1, 1, 2, 2, 3};
    auto last = std::unique(v.begin(), v.end());
    v.erase(last, v.end());
    std::println("{}", v.size());
    return 0;
}

